<?php require '_layout.php';$db=db();$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$rid=(int)$d['id'];
 if(isset($d['del'])&&$rid){$db->prepare('DELETE FROM recipes WHERE id=?')->execute([$rid]);header('Location: recipes.php');exit;}
 $sl=slug($d['title']);$v=[trim($d['title']),trim($d['intro']),$d['steps'],isset($d['active'])?1:0];
 try{if($rid){$db->prepare('UPDATE recipes SET title=?,intro=?,steps=?,active=? WHERE id=?')->execute(array_merge($v,[$rid]));}else{$db->prepare('INSERT INTO recipes(title,intro,steps,active,slug) VALUES(?,?,?,?,?)')->execute(array_merge($v,[$sl]));$rid=$db->lastInsertId();}}catch(Exception $x){$db->prepare('INSERT INTO recipes(title,intro,steps,active,slug) VALUES(?,?,?,?,?)')->execute(array_merge($v,[$sl.'-'.rand(100,999)]));$rid=$db->lastInsertId();}
 $db->prepare('DELETE FROM recipe_items WHERE recipe_id=?')->execute([$rid]);$miss=[];
 foreach(preg_split('/\r?\n/',$d['items']) as $ln){[$n,$q]=array_pad(explode('=',$ln,2),2,'1');$n=trim($n);if($n==='')continue;$p=$db->prepare('SELECT id FROM products WHERE name=? OR sku=? LIMIT 1');$p->execute([$n,$n]);
  if($pid=$p->fetchColumn())$db->prepare('INSERT INTO recipe_items(recipe_id,product_id,qty) VALUES(?,?,?)')->execute([$rid,$pid,(float)$q?:1]);else $miss[]=$n;}
 header('Location: recipes.php?ok=1'.($miss?'&miss='.urlencode(implode(', ',$miss)):''));exit;}
if(isset($_GET['id'])){$s=$db->prepare('SELECT * FROM recipes WHERE id=?');$s->execute([$id]);$r=$s->fetch()?:['id'=>0,'title'=>'','intro'=>'','steps'=>'','active'=>1];$lines=[];
 if($r['id'])foreach($db->query('SELECT p.name,i.qty FROM recipe_items i JOIN products p ON p.id=i.product_id WHERE i.recipe_id='.(int)$r['id']) as $x)$lines[]=$x['name'].'='.(0+$x['qty']);
 ahead($r['id']?'Edit recipe':'Add recipe','recipes.php');?><form method="post" class="fm"><?=csrf()?><input type="hidden" name="id" value="<?=$r['id']?>"><label>Title<input name="title" required value="<?=e($r['title'])?>"></label><label>Short intro<input name="intro" value="<?=e($r['intro'])?>"></label>
 <label>Ingredients, one per line as <code>Exact product name=quantity</code> (kg for loose items, units for packs)<textarea name="items" rows="8"><?=e(implode("\n",$lines))?></textarea></label><label>Method, one step per line<textarea name="steps" rows="8"><?=e($r['steps'])?></textarea></label><label class="chk"><input type="checkbox" name="active" <?=$r['active']?'checked':''?>> Live on the site</label><button class="btn">Save recipe</button> <a href="recipes.php">Cancel</a>
 <?php if($r['id']): ?><button class="btn ghost" name="del" value="1" onclick="return confirm('Delete this recipe?')">Delete</button><?php endif; ?></form><?php afoot();exit;}
ahead('Recipes','recipes.php');?><?=isset($_GET['ok'])?'<p class="okm">Saved</p>':''?><?=isset($_GET['miss'])?'<p class="bad">Not found, so skipped: '.e($_GET['miss']).'</p>':''?><p><a class="btn" href="?id=0">+ Add recipe</a></p><table class="tb"><tr><th>Recipe</th><th>Status</th></tr><?php foreach($db->query('SELECT * FROM recipes ORDER BY id') as $r): ?><tr><td><a href="?id=<?=$r['id']?>"><?=e($r['title'])?></a></td><td><?=badge($r['active']?'completed':'cancelled',$r['active']?'Live':'Off')?></td></tr><?php endforeach; ?></table><?php afoot();
